/** Absolute playground deep-link for a session on this agent mount. */
export function playgroundUrlForSession(request, base, sessionId) {
    const url = new URL(request.url);
    const mount = normalizeMountBase(base);
    return `${url.origin}${mount}/playground?sessionId=${encodeURIComponent(sessionId)}`;
}
/** Absolute NDJSON event-trace URL for a session on this agent mount. */
export function eventsUrlForSession(requestUrl, base, sessionId) {
    const url = new URL(requestUrl);
    const mount = normalizeMountBase(base);
    return `${url.origin}${mount}/v1/session/${encodeURIComponent(sessionId)}/events`;
}
/** Playground + trace URLs for a custom channel response body. */
export function sessionUrlsForRequest(request, base, sessionId) {
    return {
        playgroundUrl: playgroundUrlForSession(request, base, sessionId),
        traceUrl: eventsUrlForSession(request.url, base, sessionId),
    };
}
function normalizeMountBase(base) {
    if (base === "") {
        return "";
    }
    return base.startsWith("/") ? base : `/${base}`;
}
